import type { Metadata } from "next";
import Link from "next/link";
import faultPairs from "@/content/fault-pairs.json";

export const metadata: Metadata = {
  title: "Fault pairs",
  description:
    "The good and bad page of every render fault and the transition frame jump that StyleSeed's ss-verify measures, side by side.",
};

type Pair = (typeof faultPairs.pairs)[number];

// Generated by scripts/build-fault-pairs.mjs from scripts/lib/fault-pairs.mjs, the documents the
// browser tests measure (test-render-faults-browser.mjs, test-transition-jumps-browser.mjs). Each
// section's id is the class id, so a link can point at one pair (/gallery/faults#tight-inset).
export default function FaultPairsPage() {
  return (
    <main className="min-h-screen bg-white text-gray-900">
      <div className="mx-auto max-w-6xl px-4 py-12 sm:px-6">
        <header className="mb-4">
          <Link href="/gallery" className="text-sm text-gray-500 hover:text-gray-900">
            ← Gallery
          </Link>
          <h1 className="mt-4 text-4xl font-bold tracking-tight">Fault pairs</h1>
          <p className="mt-3 text-lg text-gray-600">
            For each fault that ss-verify measures on rendered screens, a page that passes beside the same
            page with the fault; the nine components it samples for frame jumps are live on{" "}
            <Link href="/gallery/transitions" className="underline hover:text-gray-900">
              /gallery/transitions
            </Link>
            .
          </p>
        </header>
        {faultPairs.pairs.map((pair) => (
          <PairSection key={pair.id} pair={pair} />
        ))}
      </div>
    </main>
  );
}

function PairSection({ pair }: { pair: Pair }) {
  const reported = pair.interactive
    ? "Reported: listed in TRANSITIONS.md; transition-jumps.mjs has no gate"
    : "Reported: listed in FAULTS.md; the gate does not fail on it";
  const badLabel = pair.gates ? "Fails the gate" : "Reported";
  return (
    <section id={pair.id} className="scroll-mt-6 border-t border-gray-200 py-8">
      <h2 className="font-mono text-xl font-semibold">{pair.id}</h2>
      <p className="mt-2 text-base text-gray-700">{pair.summary}</p>
      <dl className="mt-3 grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 text-sm">
        <dt className="text-gray-500">Rule</dt>
        <dd>{pair.rule ? <code className="font-mono text-gray-800">{pair.rule}</code> : <span className="text-gray-700">No catalog rule yet</span>}</dd>
        <dt className="text-gray-500">Status</dt>
        <dd className="text-gray-700">
          {pair.gates ? "Fails the gate: drift-report.mjs --faults --gate exits 3 on it" : reported}
        </dd>
      </dl>
      {pair.interactive && (
        <p className="mt-3 text-sm text-gray-600">Click the switch in each frame to play the change.</p>
      )}
      <div className="mt-4 grid grid-cols-1 gap-6 sm:grid-cols-2">
        <Frame label="Passes" note={`no ${pair.id} finding`} id={pair.id} doc={pair.good} interactive={pair.interactive} />
        <Frame label={badLabel} note={`${pair.id} found`} id={pair.id} doc={pair.bad} interactive={pair.interactive} />
      </div>
    </section>
  );
}

function Frame({ label, note, id, doc, interactive }: { label: string; note: string; id: string; doc: string; interactive: boolean }) {
  return (
    <figure className="min-w-0">
      <figcaption className="mb-2 text-sm">
        <span className="font-semibold text-gray-900">{label}</span>
        <span className="text-gray-500"> · {note}</span>
      </figcaption>
      <iframe
        title={`${label}: ${id}`}
        srcDoc={doc}
        sandbox={interactive ? "allow-scripts" : ""}
        className="block h-56 w-full rounded-lg border border-gray-200"
      />
    </figure>
  );
}
